  night: [
    { x: "المصدران اللذان لم تشر إليهما المادة (38): قرارات المنظمات الدولية، والتصرف بالإرادة المنفردة الصادر عن الدولة؛ وتشير إليهما بطريق غير مباشر المادة (23) من نظام محكمة قانون البحار (عبر المادة 293 من اتفاقية 1982).", pg: "330" },
    { x: "شخصية المنظمة المستقلة مسلّم بها، خاصة بعد رأي محكمة العدل الدولية الاستشاري في 11 أبريل 1949 (تعويض الأضرار)، فتنسب أعمالها إليها وحدها.", pg: "331" },
    { x: "قرارات المنظمات: كل أعمالها الانفرادية أيًا كان مسماها، ملزمة أو غير ملزمة، عدا أحكام وآراء محكمة دولية تابعة لها؛ والتوصية هي القرار غير الملزم.", pg: "331–332" },
    { x: "جانب من الفقه يرفض اعتبارها مصدرًا بأربع حجج، والرأي الراجح (ويؤيده المؤلف) يعدها مصدرًا مباشرًا ومستقلًا؛ وأصل المادة (38) وُضع عام 1920 وأُبقي عليه عام 1945.", pg: "332–335" },
    { x: "شروطها ثلاثة: الإلزام، والعمومية والتجريد، والمشروعية؛ والتوصية لا تعد مصدرًا في رأي المؤلف (وعكسه العناني) ولو قبلتها الدولة (وعكسه صلاح الدين عامر).", pg: "336" },
    { x: "العمومية: الخطاب بالصفات لا بالذوات؛ التجريد: وقائع حالية ومستقبلية غير محددة؛ وقرارا لوكربي (731) و(748) عام 1992 فرديان باطلان.", pg: "337–338" },
    { x: "القرار غير المشروع باطل في ثلاث حالات: تجاوز اختصاص المنظمة، ومخالفة قواعد التصويت، والتعارض مع قاعدة آمرة.", pg: "338" },
    { x: "بعض الفقه: تنشئ القرارات قواعد في ثلاثة أمور: إنشاء أجهزة جديدة، وتسيير عمل المنظمة، وعلاقاتها الخارجية؛ ويخالف داييه وبيليه في قرارات الأجهزة الثانوية.", pg: "339، 341" },
    { x: "المحكمة الجنائية ليوغسلافيا السابقة: القراران (808) و(827) عام 1993 (الفقرة الرابعة)؛ لجنة مكافحة الإرهاب: القرار (1373) عام 2001 وتقرير خلال تسعين يومًا.", pg: "340" },
    { x: "نشرة الأمين العام في 6 أغسطس 1999 (حفظ السلام والقانون الدولي الإنساني)، والمادة (21) من دستور منظمة الصحة العالمية (لوائح ملزمة ما لم يُخطر العضو بالرفض أو التحفظ).", pg: "341–342" },
    { x: "شروط التصرف بالإرادة المنفردة ثلاثة: النسبة إلى الدولة، والصحة والمشروعية، والاستقلال في إنتاج الآثار؛ وأكدت دوره المحكمة في قضية التجارب النووية (20 ديسمبر 1974).", pg: "344" },
    { x: "ليست تصرفات منفردة مصدرًا: تصريح قبول الاختصاص الإلزامي (المادة 2/36)، وقرارات الانضمام والتصديق والانسحاب والتحفظ (تنتج آثارها مع المعاهدة).", pg: "346–347" },
    { x: "صوره خمس: الإخطار (النمسا 1955، مصر 1957)، والاعتراف، والوعد (1978، 1993، ووعد بلفور 1917 باطل)، والتنازل، والاحتجاج.", pg: "348–350" },
    { x: "التنازل لا يُفترض وينتج أثره بذاته (مضيق كورفو 25 مارس 1948)؛ والاحتجاج تجاهله اعتراف (المصايد النرويجية 18 ديسمبر 1951، عشرة أميال بحرية).", pg: "351–353" }
  ],
